CREATE FUNCTION dg_native_bill_state(target text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b restaurant_bills%ROWTYPE;o restaurant_orders%ROWTYPE;t jsonb;status_value text;attention_value text;
BEGIN
 SELECT * INTO b FROM restaurant_bills WHERE id=target;SELECT * INTO o FROM restaurant_orders WHERE id=b.order_id;t:=dg_native_bill_totals(b.id);
 IF EXISTS(SELECT 1 FROM restaurant_financial_operations WHERE bill_id=b.id AND error_code='FINANCIAL_RECONCILIATION_REQUIRED') THEN status_value:='needs_attention';attention_value:='可信资金回执的本地投影仍待核对，请经理查询原事实。';
 ELSIF EXISTS(SELECT 1 FROM restaurant_order_dispatches dispatch JOIN restaurant_order_changes change ON change.id=dispatch.change_id WHERE change.order_id=o.id AND dispatch.error_code='POS_RECONCILIATION_REQUIRED') THEN status_value:='needs_attention';attention_value:='订单存在矛盾POS回执，资金事实保留，实际接单须经理核对。';
 ELSIF EXISTS(SELECT 1 FROM restaurant_financial_operations payment WHERE payment.bill_id=b.id AND payment.kind='payment' AND(SELECT coalesce(sum(posting.amount_minor),0) FROM restaurant_financial_postings posting JOIN restaurant_financial_operations refund ON refund.id=posting.operation_id WHERE refund.parent_payment_id=payment.id AND posting.kind='refund')>payment.amount_minor) THEN status_value:='needs_attention';attention_value:='已核实的退款超过原收款，原事实全部保留，请经理核对。';
 ELSIF(t->>'paid')::bigint-(t->>'refunded')::bigint>b.amount_minor THEN status_value:='needs_attention';attention_value:='存在已核实超付，请经理核对原收款并按权限处理退款。';
 ELSIF o.content_version<>b.order_content_version AND((t->>'paid')::bigint>0 OR(t->>'activePayments')::bigint>0) THEN status_value:='needs_attention';attention_value:='实际接单明细与原账单不一致，原资金事实保留，禁止继续按旧金额收款。';
 ELSIF(t->>'paid')::bigint>=b.amount_minor AND(t->>'activePayments')::bigint>0 THEN status_value:='needs_attention';attention_value:='已有足额资金事实但其他支付尝试仍未核实，请查询或关闭原尝试。';
 ELSIF(t->>'activePayments')::bigint>0 THEN status_value:='payment_pending';
 ELSIF b.amount_minor=0 AND(t->>'paid')::bigint=0 THEN status_value:='void';
 ELSIF(t->>'paid')::bigint>=b.amount_minor THEN status_value:=CASE WHEN(t->>'refunded')::bigint>=(t->>'paid')::bigint THEN 'refunded' WHEN(t->>'refunded')::bigint>0 THEN 'partially_refunded' ELSE 'paid' END;
 ELSE status_value:='open';END IF;
 RETURN jsonb_build_object('status',status_value,'attentionReason',attention_value,'settled',status_value IN('paid','partially_refunded','refunded','void'));
END;$dg$;

CREATE FUNCTION dg_native_bill_order_fulfilled(order_value text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT current_order.pending_change_id IS NULL AND EXISTS(SELECT 1 FROM restaurant_bills bill WHERE bill.order_id=current_order.id AND bill.status IN('paid','partially_refunded','refunded','void') AND bill.attention_reason IS NULL AND bill.order_content_version=current_order.content_version AND NOT EXISTS(SELECT 1 FROM restaurant_financial_operations operation WHERE operation.bill_id=bill.id AND(operation.status IN('queued','submitting','pending','unknown','needs_attention') OR operation.error_code='FINANCIAL_RECONCILIATION_REQUIRED'))) AND NOT EXISTS(SELECT 1 FROM restaurant_order_dispatches dispatch JOIN restaurant_order_changes change ON change.id=dispatch.change_id WHERE change.order_id=current_order.id AND(dispatch.status IN('queued','submitting','submitted','unknown') OR dispatch.error_code='POS_RECONCILIATION_REQUIRED')) AND NOT EXISTS(SELECT 1 FROM restaurant_order_lines line LEFT JOIN restaurant_kitchen_tickets ticket ON ticket.line_id=line.id WHERE line.order_id=current_order.id AND(line.quantity>line.cancelled_quantity AND(ticket.id IS NULL OR ticket.served_quantity<>line.quantity-line.cancelled_quantity) OR coalesce(ticket.pending_cancel_quantity,0)>0)) FROM restaurant_orders current_order WHERE current_order.id=order_value
$dg$;

CREATE FUNCTION dg_native_bill_refresh(action_value text,target text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b restaurant_bills%ROWTYPE;state_value jsonb;created text;
BEGIN
 SELECT * INTO b FROM restaurant_bills WHERE id=target;state_value:=dg_native_bill_state(b.id);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_bills',b.id);UPDATE restaurant_bills SET status=state_value->>'status',attention_reason=state_value->>'attentionReason',settled_at=CASE WHEN settled_at IS NULL AND(state_value->>'settled')::boolean THEN created ELSE settled_at END,version=version+1,updated_at=created WHERE id=b.id;
 IF(state_value->>'settled')::boolean AND EXISTS(SELECT 1 FROM restaurant_orders WHERE id=b.order_id AND settlement_status<>'settled') THEN PERFORM dg_native_dining_effect(action_value,'restaurant_orders',b.order_id);UPDATE restaurant_orders SET settlement_status='settled',status=CASE WHEN dg_native_bill_order_fulfilled(id) AND status<>'cancelled' THEN 'closed' ELSE dg_native_order_status(id) END,version=version+1,updated_at=created WHERE id=b.order_id;END IF;
END;$dg$;

CREATE FUNCTION dg_native_bill_party_finishable(target text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT NOT EXISTS(SELECT 1 FROM restaurant_orders current_order WHERE current_order.party_id=target AND NOT(coalesce(dg_native_bill_order_fulfilled(current_order.id),false) OR current_order.status='cancelled' AND current_order.pending_change_id IS NULL AND NOT EXISTS(SELECT 1 FROM restaurant_order_lines line WHERE line.order_id=current_order.id AND line.quantity>line.cancelled_quantity) AND NOT EXISTS(SELECT 1 FROM restaurant_order_dispatches dispatch JOIN restaurant_order_changes change ON change.id=dispatch.change_id WHERE change.order_id=current_order.id AND(dispatch.attempts<>0 OR dispatch.status<>'cancelled')) AND NOT EXISTS(SELECT 1 FROM restaurant_bills bill WHERE bill.order_id=current_order.id)))
$dg$;

CREATE FUNCTION dg_native_bill_quote_reason(target text,reader_meta jsonb DEFAULT NULL,queued_value boolean DEFAULT false) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE q restaurant_financial_quotes%ROWTYPE;fixed _dg_native_bill_quote_origins%ROWTYPE;b restaurant_bills%ROWTYPE;o restaurant_orders%ROWTYPE;p dining_parties%ROWTYPE;r restaurants%ROWTYPE;config restaurant_payment_configs%ROWTYPE;snapshot jsonb;totals jsonb;parent restaurant_financial_operations%ROWTYPE;reason_value text;
BEGIN
 SELECT * INTO q FROM restaurant_financial_quotes WHERE id=target;SELECT * INTO fixed FROM _dg_native_bill_quote_origins WHERE quote_id=q.id;IF q.id IS NULL OR fixed.quote_id IS NULL THEN RETURN '审阅不存在。';END IF;snapshot:=q.payload::jsonb;SELECT * INTO b FROM restaurant_bills WHERE id=q.bill_id;SELECT * INTO o FROM restaurant_orders WHERE id=b.order_id;SELECT * INTO p FROM dining_parties WHERE id=b.party_id;SELECT * INTO r FROM restaurants WHERE id=b.restaurant_id;SELECT * INTO config FROM restaurant_payment_configs WHERE restaurant_id=r.id;totals:=dg_native_bill_totals(b.id);
 IF reader_meta IS NOT NULL AND reader_meta-ARRAY['billId','operationId','quoteId','orderId','changeId','partyVersion','partyAccessVersion'] IS DISTINCT FROM fixed.actor_meta-ARRAY['billId','operationId','quoteId','orderId','changeId','partyVersion','partyAccessVersion'] THEN RETURN '原确认人、会话、发问人、选择或人员授权已经变化。';END IF;
 IF(q.status<>'current' AND NOT(queued_value AND q.status='consumed')) OR q.expires_at<=dg_native_dining_now() THEN RETURN '原审阅已到期、已使用或被替代，请重新核对。';END IF;
 IF NOT queued_value AND b.version<>(snapshot->>'billVersion')::bigint OR o.content_version<>(snapshot->>'orderContentVersion')::bigint OR b.order_content_version<>(snapshot->>'orderContentVersion')::bigint OR p.version<>(snapshot->>'partyVersion')::bigint OR p.access_version<>(snapshot->>'partyAccessVersion')::bigint OR r.version<>(snapshot->>'restaurantVersion')::bigint THEN RETURN '原账单、接单明细、就餐安排或归属已有新版本。';END IF;
 IF config.restaurant_id IS NULL OR config.provider_id<>'mock-payments' OR config.enabled<>1 OR config.version<>(snapshot->>'configVersion')::bigint OR config.merchant_id IS DISTINCT FROM snapshot->>'merchantId' THEN RETURN '原商户或支付连接已经变化，请重新核对。';END IF;
 IF q.kind='payment' THEN
  IF NOT dg_native_order_source(fixed.actor_meta,p.id) THEN RETURN '原顾客、人员或接待来源已失效。';END IF;reason_value:=dg_native_bill_payment_reason(o.id,fixed.actor_meta);IF reason_value IS NOT NULL THEN RETURN reason_value;END IF;
  IF NOT EXISTS(SELECT 1 FROM dining_occupancies WHERE party_id=p.id AND state='seated' AND id=snapshot->>'occupancyId') OR(totals->>'balance')::bigint<>(snapshot->>'amountMinor')::bigint OR(totals->>'balance')::bigint<=0 OR NOT queued_value AND(totals->>'activePayments')::bigint>0 THEN RETURN '当前桌位、未核实支付或剩余金额已变化，请核对原请求。';END IF;
 ELSE
  IF NOT dg_native_bill_manager(fixed.actor_meta) THEN RETURN '原退款经理授权已经失效，请由当前经理重新核对。';END IF;SELECT * INTO parent FROM restaurant_financial_operations WHERE id=q.parent_payment_id;
  IF parent.id IS NULL OR parent.bill_id<>b.id OR parent.kind<>'payment' OR NOT queued_value AND parent.version<>(snapshot->>'parentPaymentVersion')::bigint OR coalesce(dg_native_bill_refundable(parent.id,CASE WHEN queued_value THEN(SELECT id FROM restaurant_financial_operations WHERE quote_id=q.id) ELSE '' END),0)<(snapshot->>'amountMinor')::bigint OR EXISTS(SELECT 1 FROM restaurant_financial_operations WHERE bill_id=b.id AND error_code='FINANCIAL_RECONCILIATION_REQUIRED') THEN RETURN '原收款、可退余额或待核对资金事实已经变化。';END IF;
 END IF;RETURN NULL;
END;$dg$;

CREATE FUNCTION dg_native_bill_quote_create(action_value text,bill_value text,kind_value text,amount_value bigint,reason_value text,parent_value text,meta jsonb,input jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b restaurant_bills%ROWTYPE;o restaurant_orders%ROWTYPE;p dining_parties%ROWTYPE;r restaurants%ROWTYPE;config restaurant_payment_configs%ROWTYPE;parent restaurant_financial_operations%ROWTYPE;quote_value text:=input->>'_quoteId';created text;expires text;snapshot jsonb;previous_value text;
BEGIN
 SELECT * INTO b FROM restaurant_bills WHERE id=bill_value;SELECT * INTO o FROM restaurant_orders WHERE id=b.order_id;SELECT * INTO p FROM dining_parties WHERE id=b.party_id;SELECT * INTO r FROM restaurants WHERE id=b.restaurant_id;SELECT * INTO config FROM restaurant_payment_configs WHERE restaurant_id=r.id;SELECT * INTO parent FROM restaurant_financial_operations WHERE id=parent_value;
 IF config.restaurant_id IS NULL OR config.enabled<>1 OR config.provider_id<>'mock-payments' THEN PERFORM dg_native_bill_error('PAYMENT_NOT_CONFIGURED');END IF;IF quote_value IS NULL OR quote_value!~'^[a-f0-9-]{36}$' OR input->>'_confirmationHash' IS NULL OR input->>'_confirmationHash'!~'^[a-f0-9]{64}$' OR amount_value NOT BETWEEN 1 AND 100000000 THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;
 SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;expires:=dg_native_people_iso(created::timestamptz+interval '120 seconds');snapshot:=jsonb_build_object('id',quote_value,'kind',kind_value,'billId',b.id,'billVersion',b.version,'orderId',o.id,'orderContentVersion',o.content_version,'restaurantId',r.id,'restaurantVersion',r.version,'partyId',p.id,'partyVersion',p.version,'partyAccessVersion',p.access_version,'occupancyId',(SELECT id FROM dining_occupancies WHERE party_id=p.id AND state='seated'),'configVersion',config.version,'merchantId',config.merchant_id,'parentPaymentId',parent_value,'parentPaymentVersion',parent.version,'amountMinor',amount_value,'reason',reason_value,'lines',b.snapshot::jsonb,'expiresAt',expires);
 FOR previous_value IN SELECT id FROM restaurant_financial_quotes WHERE bill_id=b.id AND kind=kind_value AND status='current' LOOP PERFORM dg_native_dining_effect(action_value,'restaurant_financial_quotes',previous_value);UPDATE restaurant_financial_quotes SET status='superseded' WHERE id=previous_value;END LOOP;
 PERFORM dg_native_dining_effect(action_value,'restaurant_financial_quotes',quote_value);INSERT INTO restaurant_financial_quotes VALUES(quote_value,b.id,kind_value,parent_value,dg_native_office_hash(snapshot),snapshot::text,meta->>'actorId',meta->>'sessionId',(meta->>'focusVersion')::bigint,'current',expires,created);INSERT INTO _dg_native_bill_quote_origins VALUES(quote_value,action_value,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),meta,input->>'_confirmationHash',dg_native_office_hash(snapshot),created,expires);RETURN quote_value;
END;$dg$;
